WITH parsed AS (SELECT id, currency, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE currency = 'EUR') SELECT currency, CASE WHEN entry_price >= 31 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, SUM(CASE WHEN currency = 'USD' THEN entry_price ELSE 0 END) AS usd_entry_price, COUNT(DISTINCT currency) AS distinct_currencies FROM parsed GROUP BY currency, CASE WHEN entry_price >= 31 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY entry_price_tier DESC
